2	 *  external links) that can be linked to people, events and stories. Replaces
3	 *  the former Source / Citation / Evidence model. */
4	
5	export type DocumentFileKind = "file" | "link";
6	
7	export interface DocumentFileDB {
8	  id: string;
9	  kind: DocumentFileKind;
10	  filename: string | null;
11	  url: string;
12	  mime_type: string | null;
13	  size: number | null;
14	  created_at: string;
15	}
16	
