18	  id: string;
19	  kind: DocumentFileKind;
20	  filename: string | null;
21	  url: string;
22	  mimeType: string | null;
23	  size: number | null;
24	  createdAt: string;
25	}
26	
27	export interface DocumentDB {
28	  id: string;
29	  title: string;
30	  description: string | null;
31	  document_date: string | null;
32	  created_at: string;
33	  updated_at: string;
34	  files?: DocumentFileDB[];
35	  member_ids?: string[];
36	  event_ids?: string[];
37	  story_ids?: string[];
38	}
39	
40	export interface Document {
41	  id: string;
42	  title: string;
43	  description: string | null;
44	  documentDate: string | null;
45	  createdAt: string;
46	  updatedAt: string;
47	  files: DocumentFile[];
48	  memberIds: string[];
49	  eventIds: string[];
50	  storyIds: string[];
51	}
52	
53	/** Editable document fields captured by the dialog form. */
54	export interface DocumentInput {
55	  title: string;
56	  description: string;
57	  documentDate: string;
58	}
59	
60	/** A file the user picked but hasn't uploaded yet. Keeping the browser File
61	 * reference avoids materialising a base64 copy in React state. */
62	export interface NewDocumentFile {
63	  filename: string;
64	  file: File;
65	}
66	
67	/** The file changes to apply when saving a document. Mirrors the old
68	 *  `EvidenceOps` shape so the file-editor UI can be reused directly. */
69	export interface DocumentFileOps {
70	  addedFiles: NewDocumentFile[];
71	  addedLinks: { url: string; label?: string }[];
72	  removedIds: string[];
73	  renamed: { id: string; filename: string }[];
74	}
75	
76	/** A file streamed to the staging area, returned by the upload endpoint and
77	 *  referenced by id when the document save attaches it. */
78	export interface DocumentUploadDB {
79	  id: string;
80	  filename: string | null;
81	  mime_type: string | null;
82	  size: number | null;
83	}
84	
85	/** The full, atomic document change sent to the backend in one request. Files
86	 *  are streamed to staging first and referenced here by `attached_upload_ids`.
87	 *  Every add carries a client-generated `id` so a replayed request applies at
88	 *  most once — retries are idempotent. */
89	export interface DocumentSavePayload {
90	  title: string;
91	  description: string | null;
92	  document_date: string | null;
93	  member_ids: string[];
94	  attached_upload_ids: string[];
95	  added_links: { id: string; url: string; filename: string | null }[];
96	  removed_file_ids: string[];
97	  renamed_files: { id: string; filename: string }[];
98	}
99	
100	export function mapDocumentFileFromDB(row: DocumentFileDB): DocumentFile {
101	  return {
102	    id: row.id,
103	    kind: row.kind,
104	    filename: row.filename,
105	    url: row.url,
106	    mimeType: row.mime_type,
107	    size: row.size,
108	    createdAt: row.created_at,
109	  };
110	}
111	
112	export function mapDocumentFromDB(row: DocumentDB): Document {
113	  return {
114	    id: row.id,
115	    title: row.title,
116	    description: row.description,
117	    documentDate: row.document_date,
118	    createdAt: row.created_at,
119	    updatedAt: row.updated_at,
120	    files: (row.files ?? []).map(mapDocumentFileFromDB),
121	    memberIds: row.member_ids ?? [],
122	    eventIds: row.event_ids ?? [],
123	    storyIds: row.story_ids ?? [],
124	  };
125	}
