74	  const features = useAuthStore((state) => state.features);
75	  const restrictions = selectedTree?.restrictions ?? [];
76	  const canAccessEvents =
77	    features.includes("events") && !restrictions.includes("events");
78	  const canAccessStories =
79	    features.includes("stories") && !restrictions.includes("stories");
80	  const [searchTerm, setSearchTerm] = useState("");
81	  const [linkFilter, setLinkFilter] = useState<LinkFilter>("all");
82	  const [page, setPage] = useState(0);
83	  const [pageSize, setPageSize] = useState(25);
84	  const [dialogOpen, setDialogOpen] = useState(false);
85	  const [editingDocument, setEditingDocument] = useState<Document | null>(null);
86	  const [documentToDelete, setDocumentToDelete] = useState<Document | null>(
87	    null,
