97	
98	  const membersById = useMemo(
99	    () => new Map(members.map((member) => [member.id, member])),
100	    [members],
101	  );
102	  const eventsById = useMemo(
103	    () => new Map(events.map((event) => [event.id, event])),
104	    [events],
105	  );
