107	    () => new Map(stories.map((story) => [story.id, story])),
108	    [stories],
109	  );
110	
111	  const filteredDocuments = useMemo(() => {
112	    const normalizedSearch = searchTerm.trim().toLocaleLowerCase();
113	    return documents.filter((document) => {
114	      const unlinked =
115	        document.memberIds.length === 0 &&
116	        document.eventIds.length === 0 &&
117	        document.storyIds.length === 0;
118	      if (linkFilter === "unlinked" && !unlinked) return false;
119	      if (!normalizedSearch) return true;
120	
121	      return [
122	        document.title,
123	        document.description ?? "",
124	        ...document.files.map((file) => file.filename ?? file.url),
125	      ].some((value) => value.toLocaleLowerCase().includes(normalizedSearch));
126	    });
127	  }, [documents, linkFilter, searchTerm]);
128	
129	  const pageCount = Math.ceil(filteredDocuments.length / pageSize);
130	  const activePage = Math.min(page, Math.max(pageCount - 1, 0));
131	  const pagedDocuments = filteredDocuments.slice(
132	    activePage * pageSize,
133	    (activePage + 1) * pageSize,
134	  );
135	  const canWrite =
136	    selectedTree?.role === "owner" || selectedTree?.role === "editor";
137	
138	  const handleDelete = async () => {
139	    if (!documentToDelete) return;
140	    await removeDocument(documentToDelete.id);
141	    setDocumentToDelete(null);
142	  };
143	
144	  const handleAdd = () => {
145	    setEditingDocument(null);
146	    setDialogOpen(true);
147	  };
148	
