168	            <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
169	            <Input
170	              value={searchTerm}
171	              onChange={(event) => setSearchTerm(event.target.value)}
172	              placeholder={t("search-placeholder")}
173	              className="pl-8"
174	            />
175	          </div>
176	          <Select
177	            value={linkFilter}
178	            onValueChange={(value: LinkFilter) => setLinkFilter(value)}
179	          >
180	            <SelectTrigger className="w-44">
181	              <SelectValue />
182	            </SelectTrigger>
183	            <SelectContent>
184	              <SelectItem value="all">{t("filter-all")}</SelectItem>
185	              <SelectItem value="unlinked">{t("filter-unlinked")}</SelectItem>
186	            </SelectContent>
187	          </Select>
188	        </div>
189	      }
190	    >
191	      {!isReady || !initialized ? (
192	        <DocumentsSkeleton />
193	      ) : documents.length === 0 ? (
194	        <div className="flex flex-1 flex-col items-center justify-center rounded-lg border p-6 text-center">
195	          <FileText className="mb-3 h-10 w-10 text-muted-foreground" />
196	          <h2 className="font-medium">{t("empty-title")}</h2>
197	          <p className="mt-1 max-w-sm text-sm text-muted-foreground">
198	            {t("empty-description")}
199	          </p>
200	          {canWrite && (
201	            <Button className="mt-4" onClick={handleAdd}>
202	              <Plus />
203	              {t("add")}
204	            </Button>
205	          )}
206	        </div>
207	      ) : filteredDocuments.length === 0 ? (
208	        <p className="py-8 text-center text-sm text-muted-foreground">
209	          {t("no-results")}
210	        </p>
211	      ) : (
212	        <>
213	          <div className="space-y-3">
214	            {pagedDocuments.map((document) => (
215	              <DocumentCard
216	                key={document.id}
