226	            ))}
227	          </div>
228	          <ListPagination
229	            page={activePage}
230	            pageSize={pageSize}
231	            total={filteredDocuments.length}
232	            onPageChange={setPage}
233	            onPageSizeChange={setPageSize}
234	          />
235	        </>
236	      )}
237	
238	      <DocumentDialog
239	        open={dialogOpen}
240	        onOpenChange={setDialogOpen}
241	        document={editingDocument}
242	      />
243	      <ConfirmDeleteDialog
