279	  const setOpenSheet = useMemberSheetStore((state) => state.setOpenSheet);
280	  const navigateTo = useNavigationStore((state) => state.navigateTo);
281	  const [detailsOpen, setDetailsOpen] = useState(false);
282	  const attachments = document.files.filter((file) => file.kind === "file");
