287	  const unlinked =
288	    document.memberIds.length === 0 &&
289	    document.eventIds.length === 0 &&
290	    document.storyIds.length === 0;
291	
292	  const openDocument = () => {
293	    const file = document.files.find((item) => item.kind === "file");
294	    const link = document.files.find((item) => item.kind === "link");
295	    const attachment = file ?? link;
296	    if (attachment) {
297	      openFile(attachment);
298	    }
299	  };
300	
301	  const openFile = (file: DocumentFile) => {
302	    if (file.kind === "file") {
303	      void openMedia(file.url).catch(() => toast.error(t("open-error")));
304	    } else {
