485	                      : t("unknown-event");
486	                    return (
487	                      <Button
488	                        key={eventId}
489	                        type="button"
490	                        variant="outline"
491	                        size="sm"
492	                        className="h-7 max-w-60 gap-1 px-2"
493	                        disabled={!canNavigateTimeline}
494	                        onClick={() => navigateTo("timeline-view")}
495	                      >
496	                        <CalendarDays className="h-3.5 w-3.5 shrink-0" />
497	                        <span className="truncate">{label}</span>
498	                      </Button>
499	                    );
500	                  })}
501	                  {document.storyIds.map((storyId) => {
502	                    const story = storiesById.get(storyId);
503	                    return (
504	                      <Button
505	                        key={storyId}
506	                        type="button"
